import com.vaadin.flow.router.Route;

@Route("contact")
public class ContactView extends VerticalLayout {

    private final TextField nameField = new TextField("Name");
    private final EmailField emailField = new EmailField("Email");
    private final TextArea messageField = new TextArea("Message");

    public ContactView() {
        Component heading = new H1("Contact");

        Button sendButton = new Button("Send", event -> send());

        add(heading, nameField, emailField, messageField, sendButton);
    }

    private void send() {
        if (nameField.isEmpty()) {
            nameField.setInvalid(true);
            return;
        }
        nameField.setInvalid(false);

        Notification.show("Message sent");

        nameField.clear();
        emailField.clear();
        messageField.clear();
    }
}
